script:
frappe.ui.form.on('BOM', {
    after_load: function (frm) {
        if (frm.doc.custom_item_group && frm.doc.custom_item_group.toLowerCase() === 'chemical mix') {
            frm.clear_table('items');
            frm.set_df_property('custom_farm', 'reqd', 0);
            toggle_fields_visibility(frm);
        } else {
            reset_bom_fields(frm);
        }
    },

    // Event triggered when the main 'item' field is changed.
    item: function (frm) {
        if (frm.doc.item) {
            frappe.db.get_value('Item', frm.doc.item, 'item_group', (r) => {
                if (r.item_group) {
                    frm.set_value('custom_item_group', r.item_group);

                    if (frm.doc.custom_item_group && frm.doc.custom_item_group.toLowerCase() === 'chemical mix') {
                        frm.clear_table('items');
                        frm.set_df_property('custom_farm', 'reqd', 0);
                        toggle_fields_visibility(frm);
                        frm.doc.items.forEach(row => {
                            calculate_qty(frm, row.doctype, row.name);
                        });
                    } else {
                        reset_bom_fields(frm);
                    }
                }
            });
        }
    },

    refresh: function (frm) {
        if (frm.doc.custom_item_group && frm.doc.custom_item_group.toLowerCase() === 'chemical mix') {
            frm.set_df_property('custom_farm', 'reqd', 0);
            toggle_fields_visibility(frm);
            frm.doc.items.forEach(row => {
                calculate_qty(frm, row.doctype, row.name);
            });
        } else {
            reset_bom_fields(frm);
        }
    }
});
frappe.ui.form.on('BOM Item', {
    custom_application_rateper_ha_: function(frm, cdt, cdn) {
        if (frm.doc.custom_item_group && frm.doc.custom_item_group.toLowerCase() === 'chemical mix') {
            calculate_qty(frm, cdt, cdn);
        }
    }
});

function calculate_qty(frm, cdt, cdn) {
    const row = frappe.get_doc(cdt, cdn);
    const rate = row.custom_application_rateper_ha_ || 0;
    frappe.model.set_value(cdt, cdn, 'qty', 1 * rate);
}

function toggle_fields_visibility(frm) {
    const child_table_name = 'items';
    const all_managed_fields = [
        'is_stock_item',
        'allow_alternative_item',
        'source_warehouse',
        'custom_application_rateper_ha_'
    ];
    const child_grid = frm.fields_dict[child_table_name]?.grid;

    if (child_grid) {
        all_managed_fields.forEach(field => {
            child_grid.set_column_disp(field, false);
        });

        const fields_to_show_for_chemical_mix = [
            'custom_application_rateper_ha_'
        ];
        fields_to_show_for_chemical_mix.forEach(field => {
            child_grid.set_column_disp(field, true);
        });
    }

    const parent_fields_to_show = [
        'custom_water_ph',
        'custom_water_hardness',
    ];

    parent_fields_to_show.forEach(field => frm.toggle_display(field, true));
}

function reset_bom_fields(frm) {
    const child_table_name = 'items';
    const child_grid = frm.fields_dict[child_table_name]?.grid;

    const standard_fields = [
        'is_stock_item',
        'allow_alternative_item',
        'source_warehouse'
    ];

    const custom_fields = [
        'custom_application_rateper_ha_'
    ];

    const parent_fields_to_show = [
        'custom_mixing_instructions',
        'custom_target_pests'
    ];

    parent_fields_to_show.forEach(field => frm.toggle_display(field, false));

    if (child_grid) {
        standard_fields.forEach(field => {
            child_grid.set_column_disp(field, true);
        });
        custom_fields.forEach(field => {
            child_grid.set_column_disp(field, false);
        });
    }

    frm.set_value('allow_alternative_item', 0);
}

frappe.ui.form.on('Bed And Zone Automation', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 0 && !frm.is_new()) {
            frm.add_custom_button(__('Run Automation'), function() {
                frappe.confirm(
                    __('This will create new Bed and Zone documents. Do you want to continue?'),
                    () => {
                        frappe.call({
                            method: "createBedsAndZones",
                            args: {
                                doc_name: frm.doc.name
                            },
                            freeze: true,
                            freeze_message: "Automating zone and bed creation...",
                            callback: function(r) {
                                if (r.message) {
                                    frappe.msgprint(r.message);
                                }
                                frm.reload_doc();
                            },
                            error: function(r) {
                                if (r.message) {
                                    frappe.msgprint(r.message);
                                }
                            }
                        });
                    }
                );
            });
        }
    }
});

frappe.ui.form.on('Warehouse', {
    refresh(frm) {
        console.debug('[Warehouse Script] Starting refresh function at', new Date().toISOString());
        // Use a slight delay to ensure the map is fully loaded
        setTimeout(() => {
            console.debug('[Warehouse Script] Inside setTimeout');
            const mapControl = frm.fields_dict['custom_location'];
            if (!mapControl || !mapControl.map) {
                console.warn('[Warehouse Script] Map control or map instance not found');
                return;
            }
            const map = mapControl.map;
            console.debug('[Warehouse Script] Map instance retrieved:', map);

            // Clear existing layers from the map to avoid duplicates
            console.debug('[Warehouse Script] Clearing existing layers');
            map.eachLayer(layer => {
                if (!layer._url) { // Keep base layers, remove other layers
                    map.removeLayer(layer);
                }
            });
            console.debug('[Warehouse Script] Layers cleared');

            // Define base layers
            console.debug('[Warehouse Script] Setting up base layers');
            const satellite = L.tileLayer(
                'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
                    attribution: '© Esri',
                    maxZoom: 19
                }
            );

            const osm = L.tileLayer(
                'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    attribution: '© OpenStreetMap contributors',
                    maxZoom: 19
                }
            );

            // Add base layers and a control to switch between them
            console.debug('[Warehouse Script] Adding base layers to map');
            satellite.addTo(map);
            const baseLayers = { "Satellite View": satellite, "Street Map": osm };
            L.control.layers(baseLayers, null, { position: 'topright' }).addTo(map);
            console.debug('[Warehouse Script] Base layers and control added');

            // --- Custom GeoJSON Logic ---
            const rawGeoJSON = frm.doc.custom_raw_geojson;
            console.debug('[Warehouse Script] Raw custom_raw_geojson:', rawGeoJSON);
            if (rawGeoJSON) {
                try {
                    // Sanitize and parse the GeoJSON string
                    console.debug('[Warehouse Script] Sanitizing GeoJSON');
                    let cleanedGeoJSON = rawGeoJSON.trim();
                    if (cleanedGeoJSON.startsWith('"') && cleanedGeoJSON.endsWith('"')) {
                        cleanedGeoJSON = cleanedGeoJSON.slice(1, -1).replace(/\\"/g, '"');
                    }
                    console.debug('[Warehouse Script] Cleaned GeoJSON:', cleanedGeoJSON);

                    console.debug('[Warehouse Script] Parsing GeoJSON');
                    const geojson = JSON.parse(cleanedGeoJSON);
                    console.debug('[Warehouse Script] Parsed GeoJSON:', geojson);

                    if (geojson.type === 'FeatureCollection' && geojson.features && geojson.features.length > 0) {
                        console.debug('[Warehouse Script] Valid FeatureCollection detected, features:', geojson.features.length);
                        // Create a feature group to hold all polygons
                        const featureGroup = L.featureGroup();
                        console.debug('[Warehouse Script] Feature group created');

                        // Process each feature in the FeatureCollection
                        geojson.features.forEach((feature, index) => {
                            console.debug(`[Warehouse Script] Processing feature ${index}:`, feature);
                            if (feature.geometry && feature.geometry.type === 'Polygon') {
                                // Draw the polygon on the map
                                console.debug(`[Warehouse Script] Adding polygon for feature ${index}`);
                                const geoJsonLayer = L.geoJSON(feature, {
                                    style: {
                                        color: "#2b7fd4",
                                        weight: 3,
                                        opacity: 0.8,
                                        fillOpacity: 0.2
                                    },
                                    onEachFeature: (feature, layer) => {
                                        if (feature.properties && feature.properties.id) {
                                            console.debug(`[Warehouse Script] Binding popup for feature ${index}:`, feature.properties.id);
                                            layer.bindPopup(feature.properties.id);
                                        }
                                    }
                                }).addTo(map);
                                console.debug(`[Warehouse Script] Polygon added for feature ${index}`);

                                // Add the layer to the feature group
                                featureGroup.addLayer(geoJsonLayer);
                                console.debug(`[Warehouse Script] Feature ${index} added to feature group`);
                            } else {
                                console.warn(`[Warehouse Script] Feature ${index} is not a Polygon:`, feature);
                                frappe.msgprint(__('Invalid GeoJSON: One or more features are not Polygons.'));
                            }
                        });

                        // Fit the map view to the bounds of all polygons
                        console.debug('[Warehouse Script] Checking feature group bounds');
                        if (featureGroup.getBounds().isValid()) {
                            map.fitBounds(featureGroup.getBounds(), { padding: [50, 50] });
                            console.debug('[Warehouse Script] Map view set to bounds');
                        } else {
                            console.warn('[Warehouse Script] Invalid bounds for feature group');
                        }

                        // Calculate the centroid of all polygons
                        console.debug('[Warehouse Script] Calculating centroid');
                        let allCoordinates = [];
                        geojson.features.forEach(feature => {
                            if (feature.geometry && feature.geometry.type === 'Polygon') {
                                console.debug('[Warehouse Script] Collecting coordinates from feature:', feature.geometry.coordinates[0]);
                                allCoordinates.push(...feature.geometry.coordinates[0]);
                            }
                        });
                        console.debug('[Warehouse Script] All coordinates:', allCoordinates);

                        if (allCoordinates.length > 0) {
                            let sumLat = 0;
                            let sumLon = 0;
                            allCoordinates.forEach((coord, idx) => {
                                console.debug(`[Warehouse Script] Processing coordinate ${idx}:`, coord);
                                sumLon += coord[0];
                                sumLat += coord[1];
                            });

                            const avgLon = sumLon / allCoordinates.length;
                            const avgLat = sumLat / allCoordinates.length;
                            console.debug('[Warehouse Script] Calculated centroid:', { avgLat, avgLon });

                            // Set custom_location to GeoJSON Feature with point_type
                            const locationGeoJSON = {
                                type: "Feature",
                                geometry: {
                                    type: "Point",
                                    coordinates: [avgLon, avgLat]
                                },
                                properties: {
                                    point_type: "point"
                                }
                            };
                            let locationString = JSON.stringify(locationGeoJSON);
                            console.debug('[Warehouse Script] Setting custom_location to GeoJSON Feature:', locationString);

                            // Sanitize to prevent double-stringification
                            if (locationString.startsWith('"') && locationString.endsWith('"')) {
                                locationString = locationString.slice(1, -1);
                            }
                            console.debug('[Warehouse Script] Final custom_location value:', locationString);

                            // Set the value of the Geolocation field
                            frm.set_value('custom_location', locationString);
                            console.debug('[Warehouse Script] custom_location set');

                            // Log plain string format for reference
                            console.debug('[Warehouse Script] Plain string format (for reference):', `${avgLat},${avgLon}`);

                        } else {
                            console.warn('[Warehouse Script] No valid coordinates found for centroid');
                            frappe.msgprint(__('No valid coordinates found to calculate centroid.'));
                        }

                    } else {
                        console.warn('[Warehouse Script] Invalid GeoJSON structure:', geojson);
                        frappe.msgprint(__('Invalid GeoJSON: Must be a FeatureCollection with Polygon features.'));
                    }

                } catch (e) {
                    console.error('[Warehouse Script] Error processing GeoJSON:', e, 'Raw input:', rawGeoJSON);
                    frappe.msgprint(__('Invalid JSON format in `custom_raw_geojson`. Check the console for details.'));
                }
            } else {
                console.warn('[Warehouse Script] No GeoJSON data found in custom_raw_geojson');
            }
            console.debug('[Warehouse Script] Refresh function completed');
        }, 300);
    },

    // Trigger the refresh logic when the field's value changes
    custom_raw_geojson: function(frm) {
        console.debug('[Warehouse Script] custom_raw_geojson changed, triggering refresh');
        frm.refresh();
    }
});

frappe.ui.form.on('Pest', {
    refresh: function(frm) {
        // Set the initial value of pests_legend_color if the form is new
        if (frm.is_new()) {
            frm.set_value('pests_legend_color', '');
        }
    },
    severity: function(frm) {
        // Find the 'Moderate' severity row
        const moderateRow = frm.doc.severity.find(row => row.severity === 'Moderate');

        // If a moderate row exists, update the pests_legend_color
        if (moderateRow) {
            frm.set_value('pests_legend_color', moderateRow.color);
        }
    }
});

frappe.ui.form.on('Scouting Severity Scale', {
    color: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.severity === 'Moderate') {
            frm.set_value('pests_legend_color', row.color);
        }
    }
});

frappe.ui.form.on('Item', {
    refresh(frm) {
        toggle_custom_fields(frm);
        toggle_type_fields(frm, false);
    },
    item_group(frm) {
        toggle_custom_fields(frm, false); // true means clear old values
    },
    custom_type(frm) {
        toggle_type_fields(frm, false); // clear old values
    },
    custom_irac(frm) {
        fetch_irac_moa(frm);
    },
    custom_frac(frm) {
        fetch_frac_moa(frm);
    },
    custom_ghs(frm) {
        fetch_ghs_description(frm);
    }
});

function toggle_custom_fields(frm, clear_values = false) {
    let group_field_map = {
        "Spray Roses": ["custom_chemical_intervention_threshhold"],
        "Standard Roses": ["custom_chemical_intervention_threshhold"],
        "Summer Flowers": ["custom_chemical_intervention_threshhold"],
        "CHEMICALS": [
            "custom_type",
            "custom_ghs",
            "custom_ghs_description",
            "custom_toxicity",
            "custom_irac",
            "custom_irac_moa",
            "custom_frac",
            "custom_frac_moa",
            "custom_reentry_interval_hrs",
            "custom_active_ingredients",
            "custom_targets"
        ],
        "AVOCADO CHEMICALS": [
            "custom_type",
            "custom_ghs",
            "custom_ghs_description",
            "custom_toxicity",
            "custom_irac",
            "custom_irac_moa",
            "custom_frac",
            "custom_frac_moa",
            "custom_reentry_interval_hrs",
            "custom_active_ingredients",
            "custom_targets"
        ],
    };

    // Flatten all possible fields
    let all_fields = Object.values(group_field_map).flat();

    // If item_group not selected, hide and optionally clear all fields
    if (!frm.doc.item_group) {
        all_fields.forEach(field => {
            frm.set_df_property(field, "hidden", 1);
            if (clear_values) frm.set_value(field, null);
        });
        return;
    }

    // Determine which fields should be shown
    let fields_to_show = group_field_map[frm.doc.item_group] || [];

    // Hide (and optionally clear) irrelevant fields
    all_fields.forEach(field => {
        if (!fields_to_show.includes(field)) {
            frm.set_df_property(field, "hidden", 1);
            if (clear_values) frm.set_value(field, null);
        }
    });

    // Show relevant fields
    fields_to_show.forEach(field => {
        frm.set_df_property(field, "hidden", 0);
    });
}

function toggle_type_fields(frm, clear_values = false) {
    let type_field_map = {
        "Insecticide": [
            "custom_irac",
            "custom_irac_moa",
            "custom_reentry_interval_hrs",
            "custom_active_ingredients",
            "custom_targets"
        ],
        "Fungicide": [
            "custom_frac",
            "custom_frac_moa",
            "custom_reentry_interval_hrs",
            "custom_active_ingredients",
            "custom_targets"
        ],
        "Adjuvant": [],
        "pH Buffer": [],
    };

    const grid = frm.fields_dict["custom_targets"].grid;
    const type = frm.doc.custom_type;

    grid.toggle_display("disease", type === "Fungicide");
    grid.toggle_display("pest", type === "Insecticide");

    grid.refresh();

    let all_type_fields = Object.values(type_field_map).flat();
    if (!frm.doc.custom_type) {
        all_type_fields.forEach(field => {
            frm.set_df_property(field, "hidden", 1);
            if (clear_values) frm.set_value(field, null);
        });
        return;
    }

    let fields_to_show = type_field_map[frm.doc.custom_type] || [];

    all_type_fields.forEach(field => {
        if (!fields_to_show.includes(field)) {
            frm.set_df_property(field, "hidden", 1);
            if (clear_values) frm.set_value(field, null);
        }
    });

    fields_to_show.forEach(field => {
        frm.set_df_property(field, "hidden", 0);
    });
}

function fetch_irac_moa(frm) {
    if (!frm.doc.custom_irac || frm.doc.custom_irac.length === 0) {
        frm.set_value("custom_irac_moa", null);
        return;
    }

    // Collect all IRAC codes from the child table
    let irac_codes = frm.doc.custom_irac.map(row => row.code).filter(x => x);

    if (irac_codes.length === 0) {
        frm.set_value("custom_irac_moa", null);
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "IRAC Code",
            filters: { name: ["in", irac_codes] },
            fields: ["primary_site_of_action"]
        },
        callback: function (r) {
            if (r.message) {
                let moa_list = r.message.map(d => d.primary_site_of_action);
                frm.set_value("custom_irac_moa", moa_list.join(", "));
            }
        }
    });
}

function fetch_frac_moa(frm) {
    if (!frm.doc.custom_frac || frm.doc.custom_frac.length === 0) {
        frm.set_value("custom_frac_moa", null);
        return;
    }

    // Collect all IRAC codes from the child table
    let frac_codes = frm.doc.custom_frac.map(row => row.code).filter(x => x);

    if (frac_codes.length === 0) {
        frm.set_value("custom_frac_moa", null);
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "FRAC Code",
            filters: { name: ["in", frac_codes] },
            fields: ["mode_of_action"]
        },
        callback: function (r) {
            if (r.message) {
                let moa_list = r.message.map(d => d.mode_of_action);
                frm.set_value("custom_frac_moa", moa_list.join(", "));
            }
        }
    });
}

function fetch_ghs_description(frm) {
    if (!frm.doc.custom_ghs || frm.doc.custom_ghs.length === 0) {
        frm.set_value("custom_ghs_description", null);
        return;
    }

    // Collect all IRAC codes from the child table
    let custom_ghs = frm.doc.custom_ghs.map(row => row.code).filter(x => x);

    if (custom_ghs.length === 0) {
        frm.set_value("custom_ghs_description", null);
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "GHS Code",
            filters: { name: ["in", custom_ghs] },
            fields: ["description"]
        },
        callback: function (r) {
            if (r.message) {
                let moa_list = r.message.map(d => d.description);
                frm.set_value("custom_ghs_description", moa_list.join(", "));
            }
        }
    });
}

frappe.ui.form.on('Work Order', {
    after_load: function (frm) {
        if (frm.doc.custom_type && frm.doc.custom_type.toLowerCase() === 'application floor plan') {
            toggle_fields_visibility(frm);
        } else {
            reset_bom_fields(frm);
        }
    },

    refresh: function (frm) {
        if (frm.doc.custom_type && frm.doc.custom_type.toLowerCase() === 'application floor plan') {
            toggle_fields_visibility(frm);
        } else {
            reset_bom_fields(frm);
        }
    }
});

function toggle_fields_visibility(frm) {
    const parent_fields_to_show = [
        'custom_validation_status',
        'custom_greenhouse',
        'custom_scope',
        'custom_scope_details', 
        'custom_area',
        'custom_water_volume',
        'custom_water_ph',
        'custom_water_hardness',
        'custom_variety',
        'custom_spray_type',
        'custom_kit',
        'custom_targets',
        'custom_reentry_period_hrs',
        'custom_scheduled_application_time',
        'custom_reentry_time',
        'custom_spray_team'
    ];

    parent_fields_to_show.forEach(field => frm.toggle_display(field, true));
}

function reset_bom_fields(frm) {
    const parent_fields_to_show = [
        'custom_validation_status',
        'custom_greenhouse',
        'custom_scope',
        'custom_scope_details', 
        'custom_area',
        'custom_water_volume',
        'custom_water_ph',
        'custom_water_hardness',
        'custom_variety',
        'custom_spray_type',
        'custom_kit',
        'custom_targets',
        'custom_reentry_period_hrs',
        'custom_scheduled_application_time',
        'custom_reentry_time',
        'custom_spray_team'
    ];
    parent_fields_to_show.forEach(field => frm.toggle_display(field, false));
}

frappe.ui.form.on('Work Order', {
    refresh: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        setTimeout(function() {
            calculate_reentry_period(frm);
        }, 100);
    },
    onload: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    },
    after_load: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    },
    custom_scheduled_application_time: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_time(frm);
    },
    custom_reentry_period_hrs: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_time(frm);
    }
});

frappe.ui.form.on('Work Order Item', {
    required_items_add: function(frm, cdt, cdn) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    },
    required_items_remove: function(frm, cdt, cdn) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    },
    item_code: function(frm, cdt, cdn) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    }
});

function calculate_reentry_time(frm) {
    let scheduled_time = frm.doc.custom_scheduled_application_time;
    let reentry_hours = frm.doc.custom_reentry_period_hrs || 0;

    if (!scheduled_time) {
        frm.set_value('custom_reentry_time', null);
        return;
    }

    reentry_hours = parseFloat(reentry_hours);

    if (isNaN(reentry_hours) || reentry_hours < 0) {
        frappe.msgprint({
            title: __('Error'),
            indicator: 'red',
            message: __('Invalid reentry period. Please check the items and try again.')
        });
        frm.set_value('custom_reentry_time', null);
        return;
    }

    try {
        let scheduled_date = new Date(scheduled_time);

        if (isNaN(scheduled_date.getTime())) {
            throw new Error('Invalid scheduled application time format');
        }

        let current_utc_hours = scheduled_date.getUTCHours();
        scheduled_date.setUTCHours(current_utc_hours + reentry_hours);

        if (isNaN(scheduled_date.getTime())) {
            throw new Error('Invalid reentry time calculation result');
        }

        // Manual formatting to YYYY-MM-DD HH:MM:SS
        let YYYY = scheduled_date.getFullYear();
        let MM = String(scheduled_date.getMonth() + 1).padStart(2, '0');
        let DD = String(scheduled_date.getDate()).padStart(2, '0');
        let HH = String(scheduled_date.getHours()).padStart(2, '0');
        let mm = String(scheduled_date.getMinutes()).padStart(2, '0');
        let SS = String(scheduled_date.getSeconds()).padStart(2, '0');

        let reentry_time = `${YYYY}-${MM}-${DD} ${HH}:${mm}:${SS}`;

        frm.set_value('custom_reentry_time', reentry_time);

    } catch (error) {
        frappe.msgprint({
            title: __('Calculation Error'),
            indicator: 'red',
            message: __('Failed to calculate reentry time: {0}', [error.message])
        });
        frm.set_value('custom_reentry_time', null);
    }
}

function calculate_reentry_period(frm) {
    if (!frm.doc.required_items || frm.doc.required_items.length === 0) {
        frm.set_value('custom_reentry_period_hrs', 0);
        return;
    }

    let item_codes = [];
    frm.doc.required_items.forEach(function(item) {
        if (item.item_code) {
            item_codes.push(item.item_code);
        }
    });

    if (item_codes.length === 0) {
        frm.set_value('custom_reentry_period_hrs', 0);
        return;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Item',
            filters: {
                'name': ['in', item_codes]
            },
            fields: ['name', 'custom_reentry_interval_hrs']
        },
        callback: function(r) {
            if (r.message) {
                let max_reentry = 0;
                r.message.forEach(function(item) {
                    let reentry_hrs = item.custom_reentry_interval_hrs || 0;
                    reentry_hrs = parseFloat(reentry_hrs);
                    if (reentry_hrs > max_reentry) {
                        max_reentry = reentry_hrs;
                    }
                });
                frm.set_value('custom_reentry_period_hrs', max_reentry);
            }
        }
    });
}

frappe.ui.form.on("Work Order", {

    refresh(frm) {
        if (frm.doc.custom_type !== "Application Floor Plan") return;

        const removeButtons = () => {
            frm.remove_custom_button("Start");
            frm.remove_custom_button("Finish");
            frm.remove_custom_button("Status");
        };

        removeButtons();
        setTimeout(removeButtons, 100);
        setTimeout(removeButtons, 500);
        setTimeout(removeButtons, 1000);
    }

});

// ============================================================
//  Work Order — List Client Script
//  Adds "Approve Spray Plans" button for General Manager users.
//  Flow: farm picker → grouped-by-GH approval modal (rich cards)
//        → bulk start Work Orders + Material Transfer for Manufacture
// ============================================================

const AFP_TYPE = "Application Floor Plan";
const GM_ROLE  = "General Manager";

frappe.listview_settings["Work Order"] = {

    async onload(listview) {
        // Call a custom Server Script API that runs raw SQL to check the role —
        // raw SQL bypasses Frappe's ORM permission layer entirely.
        // See the companion Server Script: kaitet_scripts.check_gm_role
        let hasRole = false;
        try {
            const r = await frappe.call({
                method: "checkGMRole"
            });
            hasRole = r.message === true;
        } catch (e) {
            return;
        }

        if (!hasRole) return;

        injectStyles();
        listview.page.add_button("Approve Spray Plans", () => openFarmPicker());
    }
};


// ════════════════════════════════════════════════════════════
//  STEP 1 — Farm Picker
// ════════════════════════════════════════════════════════════

async function openFarmPicker() {
    let woList;
    try {
        const r = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Work Order",
                filters: [
                    ["custom_type", "=", AFP_TYPE],
                    ["status",      "=", "Not Started"]
                ],
                fields: ["name", "custom_greenhouse"],
                limit: 500,
                order_by: "custom_greenhouse asc"
            }
        });
        woList = r.message || [];
    } catch (e) {
        frappe.msgprint("Failed to load spray plans: " + (e.message || e));
        return;
    }

    if (!woList.length) {
        frappe.msgprint({
            title: "No Pending Spray Plans",
            message: "There are no unstarted Application Floor Plan work orders.",
            indicator: "blue"
        });
        return;
    }

    const farmSet = new Set();
    woList.forEach(wo => {
        const farm = deriveFarm(wo.custom_greenhouse);
        if (farm) farmSet.add(farm);
    });
    const farms = [...farmSet].sort();

    const overlay = buildOverlay();
    const modal   = buildModal();
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    overlay.addEventListener("click", e => { if (e.target === overlay) overlay.remove(); });

    modal.appendChild(buildHeader("Approve Spray Plans — Select Farm", () => overlay.remove()));

    const body = document.createElement("div");
    body.className = "sp-body";
    body.innerHTML = `
        <p style="color:#6b7280;font-size:.875rem;margin-bottom:12px;">
            Select a farm to view its pending spray plans.
        </p>
        <div class="sp-farm-grid"></div>
    `;
    modal.appendChild(body);

    farms.forEach(farm => {
        const names = woList.filter(wo => deriveFarm(wo.custom_greenhouse) === farm).map(wo => wo.name);
        const btn   = document.createElement("button");
        btn.className = "sp-farm-btn";
        btn.innerHTML = `
            <div>${farm}</div>
            <div style="font-size:.72rem;font-weight:400;color:#6b7280;margin-top:4px;">
                ${names.length} pending plan${names.length !== 1 ? "s" : ""}
            </div>`;
        btn.addEventListener("click", async () => {
            overlay.remove();
            await openApprovalModal(farm, names);
        });
        body.querySelector(".sp-farm-grid").appendChild(btn);
    });
}


// ════════════════════════════════════════════════════════════
//  STEP 2 — Approval Modal (rich cards grouped by greenhouse)
// ════════════════════════════════════════════════════════════

async function openApprovalModal(farm, woNames) {
    const overlay = buildOverlay();
    const modal   = buildModal();
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    overlay.addEventListener("click", e => { if (e.target === overlay) overlay.remove(); });
    modal.appendChild(buildHeader(`Approve Spray Plans — ${farm}`, () => overlay.remove()));

    const body = document.createElement("div");
    body.className = "sp-body";
    body.innerHTML = `<div style="text-align:center;padding:40px;color:#6b7280;">Loading spray plan details…</div>`;
    modal.appendChild(body);

    // Fetch each WO in full (parallel) to get required_items child table
    let allWorkOrders;
    try {
        allWorkOrders = await Promise.all(
            woNames.map(name => frappe.db.get_doc("Work Order", name))
        );
    } catch (e) {
        body.innerHTML = `<div style="color:#dc2626;padding:20px;">Failed to load details: ${e.message || e}</div>`;
        return;
    }

    // Check which WOs already have a draft Material Transfer for Manufacture
    let alreadyRaised = new Set();
    try {
        const seResp = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Stock Entry",
                filters: [
                    ["work_order", "in", woNames],
                    ["purpose",    "=",  "Material Transfer for Manufacture"],
                    ["docstatus",  "=",  0]
                ],
                fields: ["work_order"],
                limit: 500
            }
        });
        (seResp.message || []).forEach(se => alreadyRaised.add(se.work_order));
    } catch (e) {
        console.warn("Could not check existing stock entries:", e);
    }

    const workOrders = allWorkOrders.filter(wo => !alreadyRaised.has(wo.name));
    const pendingWOs = allWorkOrders.filter(wo =>  alreadyRaised.has(wo.name));

    body.innerHTML = "";

    // Notice for already-forwarded WOs
    if (pendingWOs.length) {
        const notice = document.createElement("div");
        notice.className = "sp-pending-notice";
        notice.innerHTML = `
            <span style="font-size:.8rem;font-weight:600;color:#92400e;">Pending Stores:</span>
            <span style="font-size:.8rem;color:#92400e;">
                ${pendingWOs.length} plan${pendingWOs.length !== 1 ? "s" : ""} already forwarded and awaiting material transfer submission —
                ${pendingWOs.map(wo =>
                    `<a href="/app/work-order/${wo.name}" target="_blank"
                        style="color:#d97706;font-weight:600;">${wo.name}</a>`
                ).join(", ")}
            </span>
        `;
        body.appendChild(notice);
    }

    if (!workOrders.length) {
        body.insertAdjacentHTML("beforeend", `
            <div style="text-align:center;padding:32px;color:#6b7280;">
                All spray plans for this farm have already been forwarded to Stores.
            </div>`);
        const footer = document.createElement("div");
        footer.className = "sp-footer";
        const closeBtn = document.createElement("button");
        closeBtn.className   = "sp-btn sp-btn-cancel";
        closeBtn.textContent = "Close";
        closeBtn.addEventListener("click", () => overlay.remove());
        footer.appendChild(closeBtn);
        modal.appendChild(footer);
        return;
    }

    // Group by greenhouse
    const byGH = {};
    workOrders.forEach(wo => {
        const gh = wo.custom_greenhouse || "Unknown";
        if (!byGH[gh]) byGH[gh] = [];
        byGH[gh].push(wo);
    });

    const checkboxMap = {};

    Object.keys(byGH).sort().forEach(gh => {
        const wos = byGH[gh];

        const section = document.createElement("div");
        section.className = "sp-gh-section";

        const ghHeader = document.createElement("div");
        ghHeader.className = "sp-gh-header";

        const ghCheck = document.createElement("input");
        ghCheck.type  = "checkbox";
        ghCheck.title = "Select / deselect all in this greenhouse";

        const ghName = document.createElement("span");
        ghName.className   = "sp-gh-name";
        ghName.textContent = gh;

        const ghMeta = document.createElement("span");
        ghMeta.className   = "sp-gh-meta";
        ghMeta.textContent = `${wos.length} plan${wos.length !== 1 ? "s" : ""}`;

        ghHeader.appendChild(ghCheck);
        ghHeader.appendChild(ghName);
        ghHeader.appendChild(ghMeta);
        section.appendChild(ghHeader);

        const ghCheckboxes = [];

        wos.forEach(wo => {
            const cb      = document.createElement("input");
            cb.type       = "checkbox";
            cb.dataset.wo = wo.name;
            checkboxMap[wo.name] = cb;
            ghCheckboxes.push(cb);

            cb.addEventListener("change", () => {
                syncGhCheckbox(ghCheck, ghCheckboxes);
                updateFooter();
            });

            section.appendChild(buildWoCard(wo, cb));
        });

        body.appendChild(section);

        ghCheck.addEventListener("change", () => {
            ghCheckboxes.forEach(c => { c.checked = ghCheck.checked; });
            ghCheck.indeterminate = false;
            updateFooter();
        });
        ghHeader.addEventListener("click", e => {
            if (e.target === ghCheck) return;
            ghCheck.checked = !ghCheck.checked;
            ghCheckboxes.forEach(c => { c.checked = ghCheck.checked; });
            ghCheck.indeterminate = false;
            updateFooter();
        });
    });

    // Footer
    const footer = document.createElement("div");
    footer.className = "sp-footer";
    modal.appendChild(footer);

    const footerInfo = document.createElement("div");
    footerInfo.className = "sp-footer-info";
    footerInfo.id = "sp-footer-info";

    const btnWrap = document.createElement("div");
    btnWrap.style.cssText = "display:flex;gap:10px;";

    const btnCancel = document.createElement("button");
    btnCancel.className   = "sp-btn sp-btn-cancel";
    btnCancel.textContent = "Cancel";
    btnCancel.addEventListener("click", () => overlay.remove());

    const btnSelectAll = document.createElement("button");
    btnSelectAll.className   = "sp-btn sp-btn-cancel";
    btnSelectAll.textContent = "Select All";
    btnSelectAll.addEventListener("click", () => {
        Object.values(checkboxMap).forEach(cb => { cb.checked = true; });
        body.querySelectorAll(".sp-gh-header input[type=checkbox]").forEach(c => {
            c.checked = true; c.indeterminate = false;
        });
        updateFooter();
    });

    const btnApprove = document.createElement("button");
    btnApprove.className   = "sp-btn sp-btn-approve";
    btnApprove.textContent = "Approve Selected";
    btnApprove.disabled    = true;
    btnApprove.id          = "sp-approve-btn";
    btnApprove.addEventListener("click", () => {
        const selected = Object.entries(checkboxMap)
            .filter(([, cb]) => cb.checked)
            .map(([name]) => name);
        if (selected.length) runApproval(selected, modal, footer);
    });

    btnWrap.append(btnCancel, btnSelectAll, btnApprove);
    footer.append(footerInfo, btnWrap);

    updateFooter();

    function updateFooter() {
        const count = Object.values(checkboxMap).filter(cb => cb.checked).length;
        document.getElementById("sp-footer-info").innerHTML =
            `<strong>${count}</strong> of <strong>${workOrders.length}</strong> plans selected`;
        const btn = document.getElementById("sp-approve-btn");
        if (btn) btn.disabled = count === 0;
    }
}


// ════════════════════════════════════════════════════════════
//  WO Card builder
// ════════════════════════════════════════════════════════════

function buildWoCard(wo, checkbox) {
    const splitLines = val => (val || "").split(/\n/).map(s => s.trim()).filter(Boolean);
    const targets    = splitLines(wo.custom_targets);
    const schedDate  = wo.custom_scheduled_application_time
        ? wo.custom_scheduled_application_time.split(" ")[0]
        : "—";
    const chemicals  = (wo.required_items || []).map(item => ({
        name: item.item_name || item.item_code,
        code: item.item_code,
        qty:  item.required_qty,
        uom:  item.stock_uom
    }));

    const card = document.createElement("div");
    card.className = "sp-wo-card";

    // Card header
    const cardHead = document.createElement("div");
    cardHead.className = "sp-wo-card-head";

    const cbWrap = document.createElement("label");
    cbWrap.className = "sp-wo-card-cb";
    cbWrap.appendChild(checkbox);

    const woInfo = document.createElement("span");
    woInfo.style.cssText = "display:flex;flex-direction:column;gap:2px;";
    woInfo.innerHTML = `
        <span style="display:flex;align-items:center;gap:8px;">
            <a href="/app/work-order/${wo.name}" target="_blank"
               style="color:#3b82f6;font-weight:700;text-decoration:none;font-size:.88rem;">
               ${wo.name}
            </a>
            <span class="sp-tag sp-tag-type">${wo.custom_spray_type || "—"}</span>
        </span>
        <span style="font-size:.75rem;color:#6b7280;font-weight:500;">${wo.custom_greenhouse || ""}</span>
    `;
    cbWrap.appendChild(woInfo);

    const schedBadge = document.createElement("span");
    schedBadge.className   = "sp-wo-sched";
    schedBadge.textContent = schedDate;

    cardHead.appendChild(cbWrap);
    cardHead.appendChild(schedBadge);
    card.appendChild(cardHead);

    // Details grid
    const grid = document.createElement("div");
    grid.className = "sp-wo-details";
    const scopeVal = [wo.custom_scope, wo.custom_scope_details].filter(Boolean).join(" — ");
    const detail = (label, value) => `
        <div class="sp-detail-item">
            <span class="sp-detail-label">${label}</span>
            <span class="sp-detail-value">${value || "—"}</span>
        </div>`;
    grid.innerHTML = `
        ${detail("Scope",        scopeVal)}
        ${detail("Area",         wo.custom_area           ? `${wo.custom_area} Ha`              : "—")}
        ${detail("Water Volume", wo.custom_water_volume   ? `${wo.custom_water_volume} L`        : "—")}
        ${detail("Water pH",     wo.custom_water_ph       || "—")}
        ${detail("Hardness",     wo.custom_water_hardness ? `${wo.custom_water_hardness} ppm`    : "—")}
        ${detail("Kit",          wo.custom_kit            || "—")}
        ${detail("CSU / WIP",    wo.wip_warehouse         || "—")}
    `;
    card.appendChild(grid);

    // Targets pills
    if (targets.length) {
        const targetsWrap = document.createElement("div");
        targetsWrap.className = "sp-wo-section";
        targetsWrap.innerHTML = `<span class="sp-detail-label">Targets</span>`;
        const pills = document.createElement("div");
        pills.className = "sp-pills";
        targets.forEach(t => {
            const p = document.createElement("span");
            p.className   = "sp-pill";
            p.textContent = t;
            pills.appendChild(p);
        });
        targetsWrap.appendChild(pills);
        card.appendChild(targetsWrap);
    }

    // Chemicals table
    if (chemicals.length) {
        const chemWrap = document.createElement("div");
        chemWrap.className = "sp-wo-section";
        chemWrap.innerHTML = `<span class="sp-detail-label">Chemicals</span>`;
        const tbl = document.createElement("table");
        tbl.className = "sp-chem-table";
        tbl.innerHTML = `
            <thead><tr>
                <th>Item Name</th>
                <th>Item Code</th>
                <th style="text-align:right">Qty</th>
                <th>UoM</th>
            </tr></thead>`;
        const tbody = document.createElement("tbody");
        chemicals.forEach(c => {
            const tr = document.createElement("tr");
            tr.innerHTML = `
                <td>${c.name}</td>
                <td style="color:#6b7280">${c.code}</td>
                <td style="text-align:right;font-weight:600">${fmtQty(c.qty)}</td>
                <td>${c.uom}</td>`;
            tbody.appendChild(tr);
        });
        tbl.appendChild(tbody);
        chemWrap.appendChild(tbl);
        card.appendChild(chemWrap);
    }

    return card;
}

function fmtQty(val) {
    if (val === null || val === undefined) return "—";
    const n = parseFloat(val);
    return isNaN(n) ? val : n % 1 === 0 ? n.toString() : n.toFixed(3).replace(/\.?0+$/, "");
}


// ════════════════════════════════════════════════════════════
//  STEP 3 — Run approval
// ════════════════════════════════════════════════════════════

async function runApproval(woNames, modal, footer) {
    footer.innerHTML = "";
    footer.style.flexDirection = "column";
    footer.style.alignItems    = "stretch";

    const title = document.createElement("div");
    title.style.cssText = "font-weight:600;margin-bottom:8px;color:#111827;";
    title.textContent   = `Approving ${woNames.length} spray plan${woNames.length !== 1 ? "s" : ""}…`;
    footer.appendChild(title);

    const progressWrap = document.createElement("div");
    progressWrap.className = "sp-progress-wrap";
    const progressBar  = document.createElement("div");
    progressBar.className   = "sp-progress-bar";
    progressBar.style.width = "0%";
    progressWrap.appendChild(progressBar);
    footer.appendChild(progressWrap);

    const log = document.createElement("div");
    log.className = "sp-status-log";
    footer.appendChild(log);

    const closeBtn = document.createElement("button");
    closeBtn.className     = "sp-btn sp-btn-cancel";
    closeBtn.textContent   = "Close";
    closeBtn.style.cssText = "margin-top:12px;align-self:flex-end;display:none;";
    closeBtn.addEventListener("click", () => {
        modal.closest(".sp-overlay").remove();
        if (typeof cur_list !== "undefined" && cur_list) cur_list.refresh();
    });
    footer.appendChild(closeBtn);

    const addLog = (html, cls = "") => {
        const line = document.createElement("div");
        if (cls) line.className = cls;
        line.innerHTML = html;
        log.appendChild(line);
        log.scrollTop = log.scrollHeight;
    };

    let done = 0, errors = 0;

    for (const woName of woNames) {
        try {
            const wo = await frappe.db.get_doc("Work Order", woName);

            if (wo.status !== "Not Started") {
                addLog(`⚠ <strong>${woName}</strong> — skipped (status: ${wo.status})`, "sp-log-warn");
                errors++; advance(); continue;
            }

            const seResp = await frappe.call({
                method: "erpnext.manufacturing.doctype.work_order.work_order.make_stock_entry",
                args: {
                    work_order_id: woName,
                    purpose: "Material Transfer for Manufacture"
                }
            });

            const seDraft = seResp.message;
            if (!seDraft) throw new Error("Stock Entry creation returned empty");

            await frappe.call({
                method: "frappe.client.save",
                args: { doc: seDraft }
            });

            addLog(`✓ <strong>${woName}</strong> — Spray plan approved. A material transfer to <strong>${wo.wip_warehouse}</strong> has been raised and is pending Stores approval`, "sp-log-ok");

        } catch (err) {
            const msg = err.message || err.exception || JSON.stringify(err);
            addLog(`✗ <strong>${woName}</strong> — ${msg}`, "sp-log-err");
            errors++;
        }

        advance();
    }

    title.textContent = `Done — ${done - errors} approved, ${errors} failed.`;
    title.style.color = errors === 0 ? "#059669" : errors === done ? "#dc2626" : "#d97706";
    closeBtn.style.display = "block";

    function advance() {
        done++;
        progressBar.style.width = `${Math.round((done / woNames.length) * 100)}%`;
    }
}


// ════════════════════════════════════════════════════════════
//  SHARED HELPERS
// ════════════════════════════════════════════════════════════

function deriveFarm(greenhouse) {
    if (!greenhouse) return null;
    const match = greenhouse.match(/^(.+?)\s+GH\b/i);
    return match ? match[1].trim() : greenhouse.split(" ")[0];
}

function syncGhCheckbox(ghCheck, ghCheckboxes) {
    const checked = ghCheckboxes.filter(c => c.checked).length;
    ghCheck.checked       = checked === ghCheckboxes.length;
    ghCheck.indeterminate = checked > 0 && checked < ghCheckboxes.length;
}

function buildOverlay() {
    const el = document.createElement("div");
    el.className = "sp-overlay";
    return el;
}

function buildModal() {
    const el = document.createElement("div");
    el.className = "sp-modal";
    return el;
}

function buildHeader(title, onClose) {
    const el  = document.createElement("div");
    el.className = "sp-header";
    const h3  = document.createElement("h3");
    h3.textContent = title;
    const btn = document.createElement("button");
    btn.className = "sp-close";
    btn.innerHTML = "&times;";
    btn.addEventListener("click", onClose);
    el.appendChild(h3);
    el.appendChild(btn);
    return el;
}

