    const style = document.createElement("style");
    style.id = "sp-approval-styles";
    style.textContent = `
        .sp-overlay {
            position:fixed; inset:0; background:rgba(0,0,0,.55);
            display:flex; align-items:center; justify-content:center; z-index:1100;
        }
        .sp-modal {
            background:#fff; border-radius:12px;
            width:94vw; max-width:1100px; max-height:90vh;
            display:flex; flex-direction:column;
            box-shadow:0 20px 60px rgba(0,0,0,.35); overflow:hidden;
        }
        .sp-header {
            padding:16px 24px; border-bottom:2px solid #e5e7eb;
            display:flex; justify-content:space-between; align-items:center;
            background:linear-gradient(135deg,#1f2937,#111827); flex-shrink:0;
        }
        .sp-header h3 { margin:0; font-size:1.05rem; font-weight:700; color:#fff; }
        .sp-close {
            background:none; border:none; font-size:26px; color:#fff; cursor:pointer;
            width:30px; height:30px; display:flex; align-items:center; justify-content:center;
            border-radius:6px; transition:background .15s;
        }
        .sp-close:hover { background:rgba(255,255,255,.18); }

        .sp-body { padding:20px 24px; overflow-y:auto; flex:1; }

        .sp-pending-notice {
            display:flex; gap:10px; align-items:flex-start;
            padding:10px 14px; background:#fffbeb; border:1.5px solid #f59e0b;
            border-radius:8px; margin-bottom:16px;
            font-size:.8rem; color:#92400e; line-height:1.5;
        }

