}

// ============================================================
//  Stock Entry — List Client Script
//  Adds "Spray Plan Transfers" button for Store Keeper users.
//  Flow: farm picker → chemical summary + SE cards by GH
//        → bulk submit selected transfers
// ============================================================

const SK_ROLE    = "Store Keeper";
const AFP_TYPE   = "Application Floor Plan";
const SE_PURPOSE = "Material Transfer for Manufacture";

frappe.listview_settings["Stock Entry"] = {

    async onload(listview) {
        // Server-side role check via raw SQL (same pattern as GM check)
        let hasRole = false;
        try {
            const r = await frappe.call({ method: "checkStoreKeeperRole" });
            hasRole = r.message === true;
        } catch (e) { return; }

        if (!hasRole) return;

        injectSkStyles();
        listview.page.add_button("Spray Plan Transfers", () => openSkFarmPicker());
    }
};


// ════════════════════════════════════════════════════════════
//  STEP 1 — Farm Picker
// ════════════════════════════════════════════════════════════

async function openSkFarmPicker() {
    // Fetch all draft Material Transfer for Manufacture SEs
    // linked to AFP work orders
    let seList;
    try {
        const r = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Stock Entry",
                filters: [
                    ["purpose",  "=", SE_PURPOSE],
                    ["docstatus", "=", 0],
                    ["work_order", "!=", ""]
                ],
                fields: ["name", "work_order"],
                limit: 500
            }
        });
        seList = r.message || [];
    } catch (e) {
        frappe.msgprint("Failed to load transfers: " + (e.message || e));
        return;
    }

    if (!seList.length) {
        frappe.msgprint({
            title: "No Pending Transfers",
            message: "There are no draft spray plan material transfers awaiting submission.",
            indicator: "blue"
        });
        return;
    }

    // Fetch work order details to filter by AFP type and get greenhouse
    const woNames = [...new Set(seList.map(se => se.work_order))];
    let woDetails;
    try {
        const r = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Work Order",
                filters: [
                    ["name", "in", woNames],
                    ["custom_type", "=", AFP_TYPE]
                ],
                fields: ["name", "custom_greenhouse", "custom_scheduled_application_time", "custom_spray_type"],
                limit: 500
            }
        });
        woDetails = r.message || [];
    } catch (e) {
        frappe.msgprint("Failed to load work order details: " + (e.message || e));
        return;
    }

    // Build a map of WO name → WO details, only for AFP type
    const woMap = {};
    woDetails.forEach(wo => { woMap[wo.name] = wo; });

    // Filter SEs to only those linked to AFP work orders
    const afpSes = seList.filter(se => woMap[se.work_order]);

    if (!afpSes.length) {
        frappe.msgprint({
            title: "No Pending Transfers",
            message: "There are no draft spray plan material transfers awaiting submission.",
            indicator: "blue"
        });
        return;
    }

    // Derive unique farms
    const farmSet = new Set();
    afpSes.forEach(se => {
        const gh   = woMap[se.work_order]?.custom_greenhouse || "";
        const farm = deriveFarm(gh);
        if (farm) farmSet.add(farm);
    });
    const farms = [...farmSet].sort();

    const overlay = buildOverlay();
    const modal   = buildModal();
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    overlay.addEventListener("click", e => { if (e.target === overlay) overlay.remove(); });
    modal.appendChild(buildHeader("Spray Plan Transfers — Select Farm", () => overlay.remove()));

    const body = document.createElement("div");
    body.className = "sp-body";
    body.innerHTML = `
        <p style="color:#6b7280;font-size:.875rem;margin-bottom:12px;">
            Select a farm to review and submit its pending chemical transfers.
        </p>
        <div class="sp-farm-grid"></div>
    `;
    modal.appendChild(body);

    farms.forEach(farm => {
        const farmSes = afpSes.filter(se => deriveFarm(woMap[se.work_order]?.custom_greenhouse) === farm);
        const btn     = document.createElement("button");
        btn.className = "sp-farm-btn";
        btn.innerHTML = `
            <div>${farm}</div>
            <div style="font-size:.72rem;font-weight:400;color:#6b7280;margin-top:4px;">
                ${farmSes.length} pending transfer${farmSes.length !== 1 ? "s" : ""}
            </div>`;
        btn.addEventListener("click", async () => {
            overlay.remove();
            await openSkTransferModal(farm, farmSes.map(se => se.name), woMap);
        });
        body.querySelector(".sp-farm-grid").appendChild(btn);
    });
}


// ════════════════════════════════════════════════════════════
//  STEP 2 — Transfer Modal
// ════════════════════════════════════════════════════════════

async function openSkTransferModal(farm, seNames, woMap) {
    const overlay = buildOverlay();
    const modal   = buildModal();
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    overlay.addEventListener("click", e => { if (e.target === overlay) overlay.remove(); });
    modal.appendChild(buildHeader(`Spray Plan Transfers — ${farm}`, () => overlay.remove()));

    const body = document.createElement("div");
    body.className = "sp-body";
    body.innerHTML = `<div style="text-align:center;padding:40px;color:#6b7280;">Loading transfer details…</div>`;
    modal.appendChild(body);

    // Fetch full SE docs (with items child table)
    let stockEntries;
    try {
        stockEntries = await Promise.all(seNames.map(n => frappe.db.get_doc("Stock Entry", n)));
    } catch (e) {
        body.innerHTML = `<div style="color:#dc2626;padding:20px;">Failed to load details: ${e.message || e}</div>`;
        return;
    }

    body.innerHTML = "";

    // ── Chemical Summary Panel ──
    // Aggregate total qty per chemical across all transfers in this farm
    const chemTotals = {}; // item_code → { name, uom, total, byGH: { gh: qty } }
    stockEntries.forEach(se => {
        const wo = woMap[se.work_order] || {};
        const gh = wo.custom_greenhouse || "Unknown";
        (se.items || []).forEach(item => {
            const key = item.item_code;
            if (!chemTotals[key]) {
                chemTotals[key] = { name: item.item_name || key, uom: item.stock_uom, total: 0, byGH: {} };
            }
            chemTotals[key].total += parseFloat(item.qty) || 0;
            chemTotals[key].byGH[gh] = (chemTotals[key].byGH[gh] || 0) + (parseFloat(item.qty) || 0);
        });
    });

    const sortedChems = Object.values(chemTotals).sort((a, b) => a.name.localeCompare(b.name));

    // Build summary card
    const summaryCard = document.createElement("div");
    summaryCard.className = "sk-summary-card";

    const summaryTitle = document.createElement("div");
    summaryTitle.className = "sk-summary-title";
    summaryTitle.textContent = `Chemicals to Issue — ${farm} (${seNames.length} transfers, ${sortedChems.length} chemical${sortedChems.length !== 1 ? "s" : ""})`;
    summaryCard.appendChild(summaryTitle);

    // Chemical tiles — one per chemical, total is the hero figure
    const tilesWrap = document.createElement("div");
    tilesWrap.className = "sk-chem-tiles";

    sortedChems.forEach(chem => {
        const ghEntries = Object.entries(chem.byGH).sort(([a], [b]) => a.localeCompare(b));
        const multipleGHs = ghEntries.length > 1;

        const tile = document.createElement("div");
        tile.className = "sk-chem-tile";

        // Total — prominent
        tile.innerHTML = `
            <div class="sk-chem-tile-name">${chem.name}</div>
            <div class="sk-chem-tile-total">
                <span class="sk-chem-tile-qty">${fmtQty(chem.total)}</span>
                <span class="sk-chem-tile-uom">${chem.uom}</span>
            </div>
        `;

        // GH breakdown — always visible, styled as secondary info
        const breakdown = document.createElement("div");
        breakdown.className = "sk-chem-breakdown";

        ghEntries.forEach(([gh, qty]) => {
            const row = document.createElement("div");
            row.className = "sk-chem-breakdown-row";
            // Shorten the GH name for display (strip farm prefix and " - KR" suffix)
            const ghShort = gh.replace(/^.+?\s+(GH\s*\d+).*$/i, "$1") || gh;
            row.innerHTML = `
                <span class="sk-chem-gh-label">${ghShort}</span>
                <span class="sk-chem-gh-qty">${fmtQty(qty)} ${chem.uom}</span>
            `;
            breakdown.appendChild(row);
        });

        tile.appendChild(breakdown);
        tilesWrap.appendChild(tile);
    });

    summaryCard.appendChild(tilesWrap);
    body.appendChild(summaryCard);

    // ── Divider ──
    const divider = document.createElement("div");
    divider.className = "sk-divider";
    divider.textContent = "Select Transfers to Submit";
    body.appendChild(divider);

    // ── SE Cards grouped by greenhouse ──
    const byGH = {};
    stockEntries.forEach(se => {
        const gh = woMap[se.work_order]?.custom_greenhouse || "Unknown";
        if (!byGH[gh]) byGH[gh] = [];
        byGH[gh].push(se);
    });

    const checkboxMap = {};

    Object.keys(byGH).sort().forEach(gh => {
        const ses = byGH[gh];

        const section = document.createElement("div");
        section.className = "sp-gh-section";

        const ghHeader = document.createElement("div");
        ghHeader.className = "sp-gh-header";

        const ghCheck = document.createElement("input");
        ghCheck.type  = "checkbox";
        ghCheck.title = "Select / deselect all in this greenhouse";

        const ghName = document.createElement("span");
        ghName.className   = "sp-gh-name";
        ghName.textContent = gh;

        const ghMeta = document.createElement("span");
        ghMeta.className   = "sp-gh-meta";
        ghMeta.textContent = `${ses.length} transfer${ses.length !== 1 ? "s" : ""}`;

        ghHeader.appendChild(ghCheck);
        ghHeader.appendChild(ghName);
        ghHeader.appendChild(ghMeta);
        section.appendChild(ghHeader);

        const ghCheckboxes = [];

        ses.forEach(se => {
            const cb      = document.createElement("input");
            cb.type       = "checkbox";
            cb.dataset.se = se.name;
            checkboxMap[se.name] = cb;
            ghCheckboxes.push(cb);

            cb.addEventListener("change", () => {
                syncGhCheckbox(ghCheck, ghCheckboxes);
                updateFooter();
            });

            section.appendChild(buildSeCard(se, cb, woMap[se.work_order]));
        });

        body.appendChild(section);

        ghCheck.addEventListener("change", () => {
            ghCheckboxes.forEach(c => { c.checked = ghCheck.checked; });
            ghCheck.indeterminate = false;
            updateFooter();
        });
        ghHeader.addEventListener("click", e => {
            if (e.target === ghCheck) return;
            ghCheck.checked = !ghCheck.checked;
            ghCheckboxes.forEach(c => { c.checked = ghCheck.checked; });
            ghCheck.indeterminate = false;
            updateFooter();
        });
    });

    // Footer
    const footer = document.createElement("div");
    footer.className = "sp-footer";
    modal.appendChild(footer);

    const footerInfo = document.createElement("div");
    footerInfo.className = "sp-footer-info";
    footerInfo.id = "sk-footer-info";

    const btnWrap = document.createElement("div");
    btnWrap.style.cssText = "display:flex;gap:10px;";

    const btnCancel = document.createElement("button");
    btnCancel.className   = "sp-btn sp-btn-cancel";
    btnCancel.textContent = "Cancel";
    btnCancel.addEventListener("click", () => overlay.remove());

    const btnSelectAll = document.createElement("button");
    btnSelectAll.className   = "sp-btn sp-btn-cancel";
    btnSelectAll.textContent = "Select All";
    btnSelectAll.addEventListener("click", () => {
        Object.values(checkboxMap).forEach(cb => { cb.checked = true; });
        body.querySelectorAll(".sp-gh-header input[type=checkbox]").forEach(c => {
            c.checked = true; c.indeterminate = false;
        });
        updateFooter();
    });

    const btnSubmit = document.createElement("button");
    btnSubmit.className   = "sp-btn sp-btn-approve";
    btnSubmit.textContent = "Submit Selected";
    btnSubmit.disabled    = true;
    btnSubmit.id          = "sk-submit-btn";
    btnSubmit.addEventListener("click", () => {
        const selected = Object.entries(checkboxMap)
            .filter(([, cb]) => cb.checked)
            .map(([name]) => name);
        if (selected.length) runSubmissions(selected, modal, footer, woMap);
    });

    btnWrap.append(btnCancel, btnSelectAll, btnSubmit);
    footer.append(footerInfo, btnWrap);

    updateFooter();

    function updateFooter() {
        const count = Object.values(checkboxMap).filter(cb => cb.checked).length;
        document.getElementById("sk-footer-info").innerHTML =
            `<strong>${count}</strong> of <strong>${stockEntries.length}</strong> transfers selected`;
        const btn = document.getElementById("sk-submit-btn");
        if (btn) btn.disabled = count === 0;
    }
}


// ════════════════════════════════════════════════════════════
//  SE Card builder
// ════════════════════════════════════════════════════════════

function buildSeCard(se, checkbox, wo) {
    wo = wo || {};
    const schedDate  = (wo.custom_scheduled_application_time || "").split(" ")[0] || "—";
    const chemicals  = (se.items || []).map(item => ({
        name: item.item_name || item.item_code,
        code: item.item_code,
        qty:  item.qty,
        uom:  item.stock_uom,
        from: item.s_warehouse,
        to:   item.t_warehouse
    }));

    const card = document.createElement("div");
    card.className = "sp-wo-card";

    // Card header
    const cardHead = document.createElement("div");
    cardHead.className = "sp-wo-card-head";

    const cbWrap = document.createElement("label");
    cbWrap.className = "sp-wo-card-cb";
    cbWrap.appendChild(checkbox);

    const seInfo = document.createElement("span");
    seInfo.style.cssText = "display:flex;flex-direction:column;gap:2px;";
    seInfo.innerHTML = `
        <span style="display:flex;align-items:center;gap:8px;">
            <a href="/app/stock-entry/${se.name}" target="_blank"
               style="color:#3b82f6;font-weight:700;text-decoration:none;font-size:.88rem;">
               ${se.name}
            </a>
            <span class="sp-tag sp-tag-type">${wo.custom_spray_type || "—"}</span>
        </span>
        <span style="font-size:.75rem;color:#6b7280;font-weight:500;">
            WO: <a href="/app/work-order/${se.work_order}" target="_blank"
                   style="color:#6b7280;text-decoration:none;">${se.work_order}</a>
        </span>
    `;
    cbWrap.appendChild(seInfo);

    const schedBadge = document.createElement("span");
    schedBadge.className   = "sp-wo-sched";
    schedBadge.textContent = schedDate;

    cardHead.appendChild(cbWrap);
    cardHead.appendChild(schedBadge);
    card.appendChild(cardHead);

    // Warehouse row
    if (chemicals.length) {
        const whRow = document.createElement("div");
        whRow.style.cssText = "padding:6px 16px;font-size:.75rem;color:#6b7280;border-bottom:1px solid #f3f4f6;display:flex;gap:16px;";
        whRow.innerHTML = `
            <span>From: <strong style="color:#374151">${chemicals[0].from || "—"}</strong></span>
            <span>To: <strong style="color:#374151">${chemicals[0].to || "—"}</strong></span>
        `;
        card.appendChild(whRow);
    }

    // Chemicals table
    const chemWrap = document.createElement("div");
    chemWrap.className = "sp-wo-section";
    const tbl = document.createElement("table");
    tbl.className = "sp-chem-table";
    tbl.innerHTML = `
        <thead><tr>
            <th>Chemical</th>
            <th>Item Code</th>
            <th style="text-align:right">Qty</th>
            <th>UoM</th>
        </tr></thead>`;
    const tbody = document.createElement("tbody");
    chemicals.forEach(c => {
        const tr = document.createElement("tr");
        tr.innerHTML = `
            <td style="font-weight:600">${c.name}</td>
            <td style="color:#6b7280">${c.code}</td>
            <td style="text-align:right;font-weight:600">${fmtQty(c.qty)}</td>
            <td>${c.uom}</td>`;
        tbody.appendChild(tr);
    });
    tbl.appendChild(tbody);
    chemWrap.appendChild(tbl);
    card.appendChild(chemWrap);

    return card;
}


// ════════════════════════════════════════════════════════════
//  STEP 3 — Bulk Submit
// ════════════════════════════════════════════════════════════

async function runSubmissions(seNames, modal, footer, woMap) {
    footer.innerHTML = "";
    footer.style.flexDirection = "column";
    footer.style.alignItems    = "stretch";

    const title = document.createElement("div");
    title.style.cssText = "font-weight:600;margin-bottom:8px;color:#111827;";
    title.textContent   = `Submitting ${seNames.length} transfer${seNames.length !== 1 ? "s" : ""}…`;
    footer.appendChild(title);

    const progressWrap = document.createElement("div");
    progressWrap.className = "sp-progress-wrap";
    const progressBar  = document.createElement("div");
    progressBar.className   = "sp-progress-bar";
    progressBar.style.width = "0%";
    progressWrap.appendChild(progressBar);
    footer.appendChild(progressWrap);

    const log = document.createElement("div");
    log.className = "sp-status-log";
    footer.appendChild(log);

    const closeBtn = document.createElement("button");
    closeBtn.className     = "sp-btn sp-btn-cancel";
    closeBtn.textContent   = "Close";
    closeBtn.style.cssText = "margin-top:12px;align-self:flex-end;display:none;";
    closeBtn.addEventListener("click", () => {
        modal.closest(".sp-overlay").remove();
        if (typeof cur_list !== "undefined" && cur_list) cur_list.refresh();
    });
    footer.appendChild(closeBtn);

    const addLog = (html, cls = "") => {
        const line = document.createElement("div");
        if (cls) line.className = cls;
        line.innerHTML = html;
        log.appendChild(line);
        log.scrollTop = log.scrollHeight;
    };

    let done = 0, errors = 0;

    for (const seName of seNames) {
        try {
            const se = await frappe.db.get_doc("Stock Entry", seName);

            if (se.docstatus !== 0) {
                addLog(`⚠ <strong>${seName}</strong> — skipped (already submitted)`, "sp-log-warn");
                errors++; advance(); continue;
            }

            await frappe.call({
                method: "frappe.client.submit",
                args: { doc: se }
            });

            const wo = woMap[se.work_order] || {};
            addLog(`✓ <strong>${seName}</strong> — submitted. Materials transferred to <strong>${se.to_warehouse}</strong>`, "sp-log-ok");

        } catch (err) {
            const msg = err.message || err.exception || JSON.stringify(err);
            addLog(`✗ <strong>${seName}</strong> — ${msg}`, "sp-log-err");
            errors++;
        }

        advance();
    }

    title.textContent = `Done — ${done - errors} submitted, ${errors} failed.`;
    title.style.color = errors === 0 ? "#059669" : errors === done ? "#dc2626" : "#d97706";
    closeBtn.style.display = "block";

    function advance() {
        done++;
        progressBar.style.width = `${Math.round((done / seNames.length) * 100)}%`;
    }
}


